function Logo({ dark = false }) { return <div className="brand"><img src={dark ? '/logo-escuro.png' : '/logo-claro.png'} alt="Quiz Cucando TI" /></div>; }
function Alert({ text, onClose }) { return text && <div className="alert" role="alert"><span>{text}</span><button onClick={onClose} aria-label="Fechar aviso">×</button></div>; }
function Empty({ icon, title, text }) { return <div className="empty"><div>{icon}</div><h3>{title}</h3><p>{text}</p></div>; }
function useRoom(pin, token) {
  const [room, setRoom] = useState(null);
  useEffect(() => {
    if (!pin || !token) return;
    let active = true, ws, timer;
    const connect = () => {
      ws = new WebSocket(`${location.protocol === 'https:' ? 'wss' : 'ws'}://${location.host}/ws`);
      ws.onopen = () => ws.send(JSON.stringify({ type: 'subscribe', pin, token }));
      ws.onmessage = event => { const data = JSON.parse(event.data); if (active && data.type === 'room') setRoom(data.room); if (active && data.type === 'room_removed') { setRoom({ phase: 'removed' }); active = false; } };
      ws.onclose = () => { if (active) timer = setTimeout(connect, 1500); };
    };
    connect(); return () => { active = false; clearTimeout(timer); ws?.close(); };
  }, [pin, token]);
  return [room, setRoom];
}

