  const max = Math.max(1, ...room.answerStats.options.map(option => option.count));
  return <section className="answer-chart" aria-label="Distribuição das respostas"><div className="chart-heading"><div><span className="eyebrow">RESULTADO DA PERGUNTA</span><h2>Como a turma respondeu</h2></div><strong>{room.answerStats.correctAnswers} de {room.answerStats.totalAnswers} acertaram</strong></div><div className="chart-bars">{room.answerStats.options.map((option, index) => <div className="chart-row" key={option.id}><span className={`chart-shape color-${index%4}`}>{['▲','◆','●','■'][index%4]}</span><div className="chart-answer"><div className="chart-label"><span>{room.question.options[index]?.text}</span>{option.correct && <b>✓ Correta</b>}</div><div className="chart-track"><div className={`chart-fill color-${index%4}`} style={{ width: `${option.count / max * 100}%` }} /></div></div><strong>{option.count}</strong></div>)}</div><p>Cada barra mostra quantos alunos escolheram a alternativa{room.question.multiple ? '; em seleção múltipla, cada escolha é contada.' : '.'}</p></section>;
