function useCountdown(openedAt, timeLimit, active) {
  const [remaining, setRemaining] = useState(0);
  useEffect(() => {
    if (!openedAt || !timeLimit || !active) { setRemaining(0); return; }
    const tick = () => setRemaining(Math.max(0, Math.ceil((openedAt + timeLimit * 1000 - Date.now()) / 1000)));
    tick(); const interval = setInterval(tick, 200); return () => clearInterval(interval);
  }, [openedAt, timeLimit, active]);
  return remaining;
}

function CountdownClock({ remaining }) {
  return <div className={`countdown-clock${remaining <= 10 ? ' countdown-danger' : ''}`} role="timer" aria-label={`Restam ${remaining} segundos`} aria-live="off"><strong>{remaining}</strong><span>s</span></div>;
}

