function Podium({ participants }) {
  const sorted = [...participants].sort(order);
  const revealOrder = sorted.slice(0, 3).map((participant, index) => ({ participant, place: index + 1 })).reverse();
  const visualOrder = [2, 1, 3].map(place => revealOrder.find(entry => entry.place === place)).filter(Boolean);
  const confettiStage = revealOrder.length * 2;
  const [stage, setStage] = useState(0);
  useEffect(() => {
    if (window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) { setStage(confettiStage); return; }
    const timers = Array.from({ length: confettiStage }, (_, index) => setTimeout(() => setStage(index + 1), 1200 + index * 1240));
    return () => timers.forEach(clearTimeout);
  }, [confettiStage]);
  useEffect(() => { if (stage < confettiStage && stage % 2 === 0) playPodiumSting(); }, [stage, confettiStage]);
  const activeIndex = revealOrder.findIndex((_, index) => stage < (index + 1) * 2);
  const announcement = stage >= confettiStage ? 'Pódio completo. Parabéns aos vencedores!' : activeIndex < 0 ? 'O pódio está começando.' : stage >= activeIndex * 2 + 1
    ? `${revealOrder[activeIndex].place}º lugar: ${revealOrder[activeIndex].participant.nickname}, ${revealOrder[activeIndex].participant.score} pontos.`
    : `${revealOrder[activeIndex].place}º lugar: ${revealOrder[activeIndex].participant.score} pontos.`;
  const colors = ['#ff5b5b', '#ffbf3f', '#32b977', '#4aa8ff', '#b36cff', '#ff78bb'];
  return <div className={`podium${stage >= confettiStage ? ' celebration' : ''}`}>
    <div className="podium-confetti" aria-hidden="true">{stage >= confettiStage && Array.from({ length: 42 }, (_, index) => <i key={index} style={{ left: `${(index * 37) % 100}%`, backgroundColor: colors[index % colors.length], animationDelay: `${(index % 9) * 95}ms`, animationDuration: `${1800 + (index % 6) * 180}ms`, transform: `rotate(${(index * 47) % 360}deg)` }} />)}</div>
    <span className="sr-only" aria-live="polite">{announcement}</span>
    <div className="confetti" aria-hidden="true">✦ ✦ ✦</div><h2>Parabéns, turma!</h2><p>Resultado final da dinâmica</p>
    <div className="winners">{visualOrder.map(({ participant, place }) => {
      const sequenceIndex = revealOrder.findIndex(entry => entry.place === place);
      const scoreStage = sequenceIndex * 2;
      const identityVisible = stage >= scoreStage + 1;
      const visible = stage >= scoreStage;
      return <div className={`podium-slot rank-${place}`} key={participant.id}>{visible && <div className={`winner place-${place}${identityVisible ? ' identity-revealed' : ''}`} aria-label={`${place}º lugar, ${participant.score} pontos`}>
        <span className="winner-place">{place}º LUGAR</span><small className="winner-points">{participant.score.toLocaleString('pt-BR')} pontos</small>
        <div className="winner-identity" aria-hidden={!identityVisible}><strong>{participant.avatar}</strong><b>{participant.nickname}</b></div>
      </div>}</div>;
    })}</div>
    {stage >= confettiStage && sorted.length > 3 && <div className="all-scores">{sorted.slice(3).map((participant, index) => <div key={participant.id}><span>{index + 4}º {participant.avatar} {participant.nickname}</span><b>{participant.score} pts</b></div>)}</div>}
  </div>;
}

